{
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "weight": 10,
      "explanation": "The vignette directly says that reminders of the accident lead her to avoid and control her thoughts and activities.",
      "quote": "her distress is amplified when she encounters reminders of the accident ... To manage this fear, she tries hard not to think about the trauma ... and she also avoids going out"
    },
    "Triggers__Threat": {
      "weight": 8,
      "explanation": "The cues are described as shifting her from settled to alarmed and confirming that harm can recur, indicating they intensify current threat.",
      "quote": "These cues quickly shift her from feeling settled into a state of alarm"
    },
    "Triggers__Memory": {
      "weight": 8,
      "explanation": "The reminders of danger are linked to re-experiencing the event in real time, showing that cues activate trauma memory.",
      "quote": "moments in which she feels as if the event is happening again in real time"
    },
    "Triggers__Negative_Appraisals": {
      "weight": 8,
      "explanation": "Encountering reminders of the accident strengthens her belief that harm can recur without warning.",
      "quote": "reminders of the accident, which quickly confirm her expectation that harm can recur without warning"
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Her beliefs that others cannot be trusted and that she must be especially careful are followed by guardedness and avoidance.",
      "quote": "These beliefs have made her increasingly guarded in social and practical situations"
    },
    "Negative_Appraisals__Threat": {
      "weight": 8,
      "explanation": "Her belief that one must be especially careful because one never knows what will happen next implies ongoing current danger.",
      "quote": "she must be especially careful because one never knows what will happen next"
    },
    "Negative_Appraisals__Memory": {
      "weight": 2,
      "explanation": "The vignette does not clearly state that her beliefs change the trauma memory itself, only that the beliefs arise after the memory experiences.",
      "quote": "\""
    },
    "Negative_Appraisals__Triggers": {
      "weight": 4,
      "explanation": "Her beliefs are described as being amplified when she encounters reminders, but the text does not show the beliefs generating the triggers.",
      "quote": "her distress is amplified when she encounters reminders of the accident"
    },
    "Memory__Maladaptive_Strategies": {
      "weight": 4,
      "explanation": "Intrusive reliving is followed by coping efforts, but the passage does not clearly say the memory causes those strategies.",
      "quote": "When she remembers what happened ... To manage this fear, she tries hard not to think about the trauma"
    },
    "Memory__Threat": {
      "weight": 8,
      "explanation": "The reliving is explicitly said to intensify her sense that danger remains close and immediate.",
      "quote": "These experiences appear to intensify her sense that danger remains close and immediate"
    },
    "Memory__Negative_Appraisals": {
      "weight": 6,
      "explanation": "Her intrusive reliving and disorientation occur in the context of a strongly cautious worldview, suggesting the memory experience contributes to those appraisals.",
      "quote": "Her account of the trauma is dominated by intrusive sensory reliving ... In response, she has developed a strongly cautious view of the world"
    },
    "Memory__Triggers": {
      "weight": 6,
      "explanation": "Her memory is cued by reminders and related stimuli, especially when she remembers the event and hears sounds from it.",
      "quote": "When she remembers what happened, she sometimes hears the sounds that were present during the frightening event"
    },
    "Threat__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "Her sense of current danger appears to motivate attempts to suppress thoughts and avoid situations.",
      "quote": "These experiences appear to intensify her sense that danger remains close and immediate. In response, she has developed... To manage this fear, she tries hard not to think about the trauma"
    },
    "Threat__Memory": {
      "weight": 6,
      "explanation": "The text suggests that feeling danger as immediate is associated with her reliving experiences, though it does not state a direct causal link.",
      "quote": "These experiences appear to intensify her sense that danger remains close and immediate"
    },
    "Threat__Negative_Appraisals": {
      "weight": 4,
      "explanation": "The vignette links her sense of danger with cautious beliefs, but it does not clearly state that threat causes the beliefs.",
      "quote": "danger remains close and immediate. In response, she has developed a strongly cautious view"
    },
    "Threat__Triggers": {
      "weight": 2,
      "explanation": "Threat is clearly evoked by reminders in the vignette, but the text does not show threat producing triggers.",
      "quote": "when she encounters reminders of the accident"
    },
    "Maladaptive_Strategies__Memory": {
      "weight": 2,
      "explanation": "The vignette says avoidance and suppression give short-term relief, but it does not explicitly state they affect her intrusive memory.",
      "quote": "These strategies provide short-term relief"
    },
    "Maladaptive_Strategies__Negative_Appraisals": {
      "weight": 4,
      "explanation": "Her avoidance and guardedness preserve a restricted life and distress, but the text does not clearly say they generate the negative beliefs.",
      "quote": "These strategies provide short-term relief, they leave her life increasingly restricted and distant"
    }
  }
}
